def kindlop():
    # Small ember hare: long drooping ears with glowing tips, a flame puff tail.
    return [
        P([(38, 30), (50, 22), (54, 30), (48, 40), (40, 40)], "light"),        # flame tail
        P([(44, 28), (50, 26), (49, 33), (45, 36)], "mid", outline=False),
        E(30, 41, 12, 10, "mid"),                                               # body
        E(24, 51, 5, 3, "dark"), E(36, 51, 5, 3, "dark"),                       # feet
        P([(24, 22), (34, 18), (40, 26), (38, 40), (32, 42), (30, 30)], "dark"),  # far ear
        E(20, 29, 10, 9, "light"),                                              # head
        P([(20, 21), (30, 17), (36, 24), (34, 38), (28, 40), (26, 28)], "dark"),  # near ear
        P([(30, 36), (36, 34), (36, 42), (30, 44)], "light"),                   # ear tip ember
        eye(14, 26, big=True),
        Stamp(10, 33, ["0.0", ".0."]),                                          # mouth
        Stamp(18, 32, ["11"]),                                                  # cheek
    ]


