DESIGNS = {
    "Kindlop": kindlop, "Smoldrake": smoldrake, "Calderox": calderox,
    "Puddlet": puddlet, "Riptail": riptail, "Leviarch": leviarch,
    "Mossling": mossling, "Thornback": thornback, "Verdantusk": verdantusk,
    "Zippit": zippit, "Glimmerax": glimmerax,
    "Shalebat": shalebat, "Obsidroth": obsidroth,
    "Zephlet": zephlet, "Tempestrel": tempestrel,
    "Wickit": wickit, "Lumenewt": lumenewt,
    "Mirkmole": mirkmole, "Duskdigger": duskdigger,
    "Kelpup": kelpup, "Kelphound": kelphound,
}
BACK_DROP = 8


def main() -> None:
    out = os.path.join(os.path.dirname(__file__), "..", "..", "art", "era1", "spirlings")
    os.makedirs(out, exist_ok=True)
    for name, fn in DESIGNS.items():
        parts = fn()
        render(parts).save(os.path.join(out, f"{name.lower()}_front.png"))
        back = shift_down(render(parts, back=True).mirrored(), BACK_DROP)
        back.save(os.path.join(out, f"{name.lower()}_back.png"))


if __name__ == "__main__":
    main()
